    sn: { title: "UYAI KUMUSHA", verses: [{ num: 1, lines: ["Uyai kumusha, uyai kumusha, imi makaneta, uyai kumusha;", "Nemwoyo wose, Jesu anomudana,", "Achidana, O mutadzi, uyai kumusha!"] }], chorus: null },
    nd: { title: "BUYA EKHAYA", verses: [{ num: 1, lines: ["Buya ekhaya, buya ekhaya, lina elidiniweyo, buya ekhaya;", "Ngenhliziyo yonke, uJesu uyalibiza,", "Ebizwa, O soni, buya ekhaya!"] }], chorus: null }
