    sn: { title: "ISHE NDINODA KUVE MKRISTU", verses: [{ num: 1, lines: ["Ishe ndinoda kuve Mkristu mumwoyo mangu,", "Ishe ndinoda kuve Mkristu mumwoyo mangu;", "Mumwoyo mangu, mumwoyo mangu,", "Ishe ndinoda kuve Mkristu mumwoyo mangu."] }], chorus: null },
    nd: { title: "NKOSI NGIFUN' UKUBA NGUMKRISTU", verses: [{ num: 1, lines: ["Nkosi ngifun' ukuba nguMkristu enhliziyweni yami,", "Nkosi ngifun' ukuba nguMkristu enhliziyweni yami;", "Enhliziyweni yami, enhliziyweni yami,", "Nkosi ngifun' ukuba nguMkristu enhliziyweni yami."] }], chorus: null }
