    sn: { title: "NZVIMBO YAKAKWIRIRA", verses: [{ num: 1, lines: ["Ishe ndisimudzei mundimise,", "Nokutenda, munyika yokudenga,", "Nzvimbo yakakwirira kupfuura yandawana;", "Ishe, dzikamisai tsoka dzangu panzvimbo yakakwirira."] }], chorus: null },
