    sn: { title: "MBAMBERI VATENDI (PFUPI)", verses: [{ num: 1, lines: ["Mbamberi, vatendi, muchifamba sehondo,", "Muchinjikwa wa Jesu uchienda mberi."] }], chorus: null },
    nd: { title: "QHUBEKA MAKRISTU (EMFANE)", verses: [{ num: 1, lines: ["Qhubeka, maKristu, lihamba njengempi,", "Isiphambano sika Jesu sihamba phambili."] }], chorus: null }
